     1→//! T074: Integration tests for MQTT fan control.
     2→//!
     3→//! Tests the MQTT client and fan controller integration with zone-based speed control.
     4→
     5→use rustride::integrations::mqtt::{
     6→    DefaultFanController, DefaultMqttClient, FanController, FanProfile, MqttClient, MqttConfig,
     7→    MqttError, PayloadFormat, QoS,
