    12→/// Test MQTT client creation and basic state.
    13→#[test]
    14→fn test_mqtt_client_creation() {
    15→    let client = DefaultMqttClient::new();
    16→    assert!(!client.is_connected());
    17→}
    18→
    19→/// Test MQTT config defaults.
    20→#[test]
    21→fn test_mqtt_config_defaults() {
    22→    let config = MqttConfig::default();
    23→    assert!(!config.enabled);
    24→    assert_eq!(config.broker_host, "localhost");
    25→    assert_eq!(config.broker_port, 1883);
    26→    assert!(!config.use_tls);
    27→    assert!(config.username.is_none());
    28→    assert_eq!(config.keep_alive_secs, 60);
    29→    assert_eq!(config.reconnect_interval_secs, 5);
    30→}
    31→
    32→/// Test fan profile defaults.
    33→#[test]
    34→fn test_fan_profile_defaults() {
    35→    let profile = FanProfile::default();
    36→    assert!(!profile.name.is_empty());
    37→    assert!(!profile.mqtt_topic.is_empty());
    38→    assert!(profile.use_set_suffix);
    39→    assert_eq!(profile.payload_format, PayloadFormat::JsonSpeed);
    40→    assert!(profile.use_power_zones);
    41→    assert_eq!(profile.change_delay_secs, 3);
    42→
    43→    // Zone speeds should have 7 entries
    44→    assert_eq!(profile.zone_speeds.len(), 7);
    45→    // Zone 1 should be low/off
    46→    assert_eq!(profile.zone_speeds[0], 0);
    47→    // Zone 7 should be max
    48→    assert_eq!(profile.zone_speeds[6], 100);
    49→}
