    51→/// Test fan profile command topic generation.
    52→#[test]
    53→fn test_fan_profile_command_topic() {
    54→    let mut profile = FanProfile {
    55→        mqtt_topic: "home/fan/bedroom".to_string(),
    56→        use_set_suffix: true,
    57→        ..Default::default()
    58→    };
    59→
    60→    // With /set suffix
    61→    assert_eq!(profile.command_topic(), "home/fan/bedroom/set");
    62→
    63→    // Without /set suffix
    64→    profile.use_set_suffix = false;
    65→    assert_eq!(profile.command_topic(), "home/fan/bedroom");
    66→}
    67→
    68→/// Test fan profile payload formatting.
    69→#[test]
    70→fn test_fan_profile_payload_formats() {
    71→    let mut profile = FanProfile {
    72→        payload_format: PayloadFormat::SpeedOnly,
    73→        ..Default::default()
    74→    };
    75→
    76→    // Speed only format
    77→    assert_eq!(profile.format_payload(75, true), "75");
    78→    assert_eq!(profile.format_payload(0, false), "0");
    79→
    80→    // JSON speed format
    81→    profile.payload_format = PayloadFormat::JsonSpeed;
    82→    assert_eq!(profile.format_payload(75, true), r#"{"speed": 75}"#);
    83→
    84→    // JSON speed + on/off format
    85→    profile.payload_format = PayloadFormat::JsonSpeedOnOff;
    86→    assert_eq!(
    87→        profile.format_payload(75, true),
    88→        r#"{"speed": 75, "on": true}"#
    89→    );
    90→    assert_eq!(
    91→        profile.format_payload(0, false),
    92→        r#"{"speed": 0, "on": false}"#
    93→    );
    94→
    95→    // Percentage format
    96→    profile.payload_format = PayloadFormat::Percentage;
    97→    assert_eq!(profile.format_payload(75, true), "75%");
    98→}
