   100→/// Test fan profile zone-to-speed mapping.
   101→#[test]
   102→fn test_fan_profile_zone_speed_mapping() {
   103→    let profile = FanProfile::default();
   104→
   105→    // Zone 1 should be 0%
   106→    assert_eq!(profile.speed_for_zone(1), 0);
   107→
   108→    // Zone 3 should be moderate
   109→    assert_eq!(profile.speed_for_zone(3), 40);
   110→
   111→    // Zone 7 should be max
   112→    assert_eq!(profile.speed_for_zone(7), 100);
   113→
   114→    // Zone 0 (invalid) should clamp to zone 1
   115→    assert_eq!(profile.speed_for_zone(0), 0);
   116→
   117→    // Zone 10 (invalid) should clamp to zone 7
   118→    assert_eq!(profile.speed_for_zone(10), 100);
   119→}
