   121→/// Test custom zone speed mapping.
   122→#[test]
   123→fn test_fan_profile_custom_zone_speeds() {
   124→    // Set a "threshold only" profile (fan only at high zones)
   125→    let profile = FanProfile {
   126→        zone_speeds: [0, 0, 0, 25, 50, 75, 100],
   127→        ..Default::default()
   128→    };
   129→
   130→    assert_eq!(profile.speed_for_zone(1), 0);
   131→    assert_eq!(profile.speed_for_zone(2), 0);
   132→    assert_eq!(profile.speed_for_zone(3), 0);
   133→    assert_eq!(profile.speed_for_zone(4), 25);
   134→    assert_eq!(profile.speed_for_zone(5), 50);
   135→    assert_eq!(profile.speed_for_zone(6), 75);
   136→    assert_eq!(profile.speed_for_zone(7), 100);
   137→}
