   168→/// Test fan controller start and state initialization.
   169→#[tokio::test]
   170→async fn test_fan_controller_start() {
   171→    let mqtt_client = Arc::new(DefaultMqttClient::new());
   172→    let fan_controller = DefaultFanController::new(mqtt_client);
   173→
   174→    let profile = FanProfile {
   175→        id: Uuid::new_v4(),
   176→        name: "Test Fan".to_string(),
   177→        mqtt_topic: "home/fan/test".to_string(),
   178→        ..FanProfile::default()
   179→    };
   180→    let profile_id = profile.id;
   181→
   182→    fan_controller.configure(vec![profile]);
   183→
   184→    // Start the controller
   185→    let result = fan_controller.start().await;
   186→    assert!(result.is_ok());
   187→
   188→    // States should now be initialized
   189→    let states = fan_controller.get_states();
   190→    assert_eq!(states.len(), 1);
   191→
   192→    // Check initial state
   193→    let state = states.get(&profile_id).unwrap();
   194→    assert_eq!(state.current_speed, 0);
   195→    assert_eq!(state.last_zone, 1);
   196→    assert!(state.auto_mode);
   197→    assert!(!state.is_on);
   198→}
