    10→/// Trait for MQTT client implementations
    11→pub trait MqttClient: Send + Sync {
    12→    /// Connect to the MQTT broker
    13→    fn connect(
    14→        &self,
    15→        config: &MqttConfig,
    16→    ) -> impl std::future::Future<Output = Result<(), MqttError>> + Send;
    17→
    18→    /// Disconnect from the broker
    19→    fn disconnect(&self) -> impl std::future::Future<Output = Result<(), MqttError>> + Send;
    20→
    21→    /// Check if connected
    22→    fn is_connected(&self) -> bool;
    23→
    24→    /// Publish a message to a topic
    25→    fn publish(
    26→        &self,
    27→        topic: &str,
    28→        payload: &str,
    29→        qos: QoS,
    30→    ) -> impl std::future::Future<Output = Result<(), MqttError>> + Send;
    31→
    32→    /// Subscribe to a topic
    33→    fn subscribe(
    34→        &self,
    35→        topic: &str,
    36→        qos: QoS,
    37→    ) -> impl std::future::Future<Output = Result<(), MqttError>> + Send;
    38→
    39→    /// Unsubscribe from a topic
    40→    fn unsubscribe(
    41→        &self,
    42→        topic: &str,
    43→    ) -> impl std::future::Future<Output = Result<(), MqttError>> + Send;
    44→
    45→    /// Subscribe to connection events
    46→    fn subscribe_events(&self) -> broadcast::Receiver<MqttEvent>;
    47→}
