   289→    fn spawn_reconnection_task(
   290→        state: Arc<RwLock<ConnectionState>>,
   291→        config: Arc<RwLock<Option<MqttConfig>>>,
   292→        event_tx: broadcast::Sender<MqttEvent>,
   293→        client: Arc<RwLock<Option<AsyncClient>>>,
   294→        event_loop_handle: Arc<RwLock<Option<JoinHandle<()>>>>,
   295→        reconnect_enabled: Arc<AtomicBool>,
   296→        reconnect_attempt: Arc<std::sync::atomic::AtomicU32>,
