   298→        tokio::spawn(async move {
   299→            loop {
   300→                // Check if reconnection is still enabled (user might disconnect manually)
   301→                if !reconnect_enabled.load(Ordering::SeqCst) {
   302→                    tracing::info!("MQTT reconnection disabled, stopping reconnection attempts");
   303→                    *state.write().await = ConnectionState::Disconnected;
   304→                    let _ = event_tx.send(MqttEvent::Disconnected);
   305→                    break;
   306→                }
   307→
   308→                // Get the config, bail if it's been cleared
   309→                let cfg = match config.read().await.clone() {
   310→                    Some(cfg) => cfg,
   311→                    None => {
   312→                        tracing::warn!("MQTT config cleared, stopping reconnection");
   313→                        *state.write().await = ConnectionState::Disconnected;
   314→                        let _ = event_tx.send(MqttEvent::Disconnected);
   315→                        break;
   316→                    }
   317→                };
   318→
   319→                // Increment attempt counter
   320→                let attempt = reconnect_attempt.fetch_add(1, Ordering::SeqCst) + 1;
   321→
   322→                // Check if we've exceeded max reconnection attempts
