   331→                        *state.write().await = ConnectionState::Disconnected;
   332→                        let _ = event_tx.send(MqttEvent::ReconnectionFailed {
   333→                            attempts: attempt - 1,
   334→                            reason: format!(
   335→                                "Exceeded maximum reconnection attempts ({})",
   336→                                max_attempts
   337→                            ),
   338→                        });
   339→                        let _ = event_tx.send(MqttEvent::Disconnected);
