   425→impl MqttClient for DefaultMqttClient {
   426→    async fn connect(&self, config: &MqttConfig) -> Result<(), MqttError> {
   427→        if !config.enabled {
   428→            return Err(MqttError::ConfigError("MQTT is disabled".to_string()));
   429→        }
   430→
   431→        *self.state.write().await = ConnectionState::Connecting;
   432→        *self.config.write().await = Some(config.clone());
   433→
   434→        // Enable auto-reconnection for this connection
   435→        self.reconnect_enabled.store(true, Ordering::SeqCst);
   436→
   437→        tracing::info!(
   438→            "Connecting to MQTT broker at {}:{}",
   439→            config.broker_host,
   440→            config.broker_port
   441→        );
   442→
   443→        // Create MQTT options with broker configuration
   444→        let mut mqtt_options = MqttOptions::new(
   445→            &config.client_id,
   446→            &config.broker_host,
   447→            config.broker_port,
   448→        );
   449→        mqtt_options.set_keep_alive(Duration::from_secs(config.keep_alive_secs as u64));
   450→        mqtt_options.set_connection_timeout(config.connection_timeout_secs.into());
   451→
   452→        // TODO (subtask 3.1): Add TLS configuration when use_tls is enabled
   453→        // TODO (subtask 3.2): Add credentials from keyring when username is set
   454→
   455→        // Create the AsyncClient and EventLoop
   456→        // Buffer size of 10 is sufficient for fan control operations
   457→        let (client, eventloop) = AsyncClient::new(mqtt_options, 10);
   458→
   459→        // Store the client for publishing/subscribing
   460→        *self.client.write().await = Some(client);
   461→
   462→        // Spawn the event loop task to poll for MQTT events
   463→        // The actual connection is established when the event loop starts polling
   464→        let handle = Self::spawn_event_loop_task(
   465→            eventloop,
   466→            Arc::clone(&self.state),
   467→            Arc::clone(&self.config),
   468→            self.event_tx.clone(),
   469→            Arc::clone(&self.client),
   470→            Arc::clone(&self.event_loop_handle),
   471→            Arc::clone(&self.reconnect_enabled),
   472→        );
   473→        *self.event_loop_handle.write().await = Some(handle);
   474→
   475→        tracing::info!("MQTT event loop started, waiting for connection...");
   476→
   477→        Ok(())
   478→    }
