   480→    async fn disconnect(&self) -> Result<(), MqttError> {
   481→        // Disable auto-reconnection first to prevent reconnection tasks from running
   482→        self.reconnect_enabled.store(false, Ordering::SeqCst);
   483→
   484→        // Abort the event loop task if running
   485→        if let Some(handle) = self.event_loop_handle.write().await.take() {
   486→            handle.abort();
   487→            tracing::debug!("MQTT event loop task aborted");
   488→        }
   489→
   490→        // Clear the client
   491→        *self.client.write().await = None;
   492→
   493→        *self.state.write().await = ConnectionState::Disconnected;
   494→        *self.config.write().await = None;
   495→
   496→        let _ = self.event_tx.send(MqttEvent::Disconnected);
   497→
   498→        tracing::info!("Disconnected from MQTT broker");
