    13→/// Trait for MQTT client implementations
    14→pub trait MqttClient: Send + Sync {
    15→    /// Connect to the MQTT broker
    16→    fn connect(
    17→        &self,
    18→        config: &MqttConfig,
    19→    ) -> impl std::future::Future<Output = Result<(), MqttError>> + Send;
    20→
    21→    /// Disconnect from the broker
    22→    fn disconnect(&self) -> impl std::future::Future<Output = Result<(), MqttError>> + Send;
    23→
    24→    /// Check if connected
    25→    fn is_connected(&self) -> bool;
    26→
    27→    /// Get the current connection state
    28→    fn connection_state(&self) -> ConnectionState;
    29→
    30→    /// Publish a message to a topic
    31→    fn publish(
    32→        &self,
    33→        topic: &str,
    34→        payload: &str,
    35→        qos: QoS,
    36→    ) -> impl std::future::Future<Output = Result<(), MqttError>> + Send;
    37→
    38→    /// Subscribe to a topic
    39→    fn subscribe(
    40→        &self,
    41→        topic: &str,
    42→        qos: QoS,
    43→    ) -> impl std::future::Future<Output = Result<(), MqttError>> + Send;
    44→
    45→    /// Unsubscribe from a topic
    46→    fn unsubscribe(
    47→        &self,
    48→        topic: &str,
    49→    ) -> impl std::future::Future<Output = Result<(), MqttError>> + Send;
    50→
    51→    /// Subscribe to connection events
    52→    fn subscribe_events(&self) -> broadcast::Receiver<MqttEvent>;
    53→}
