    55→/// Connection state
    56→#[derive(Debug, Clone, PartialEq, Eq)]
    57→pub enum ConnectionState {
    58→    /// Not connected and not attempting to connect
    59→    Disconnected,
    60→    /// Attempting initial connection
    61→    Connecting,
    62→    /// Successfully connected to broker
    63→    Connected,
    64→    /// Connection was lost, preparing to reconnect
    65→    ConnectionLost,
    66→    /// Actively attempting reconnection
    67→    Reconnecting { attempt: u32 },
    68→}
    69→
    70→/// Default MQTT client implementation
    71→pub struct DefaultMqttClient {
    72→    state: Arc<RwLock<ConnectionState>>,
    73→    config: Arc<RwLock<Option<MqttConfig>>>,
    74→    event_tx: broadcast::Sender<MqttEvent>,
    75→    /// The rumqttc async client for publishing and subscribing
    76→    client: Arc<RwLock<Option<AsyncClient>>>,
    77→    /// Handle to the spawned event loop task (for aborting on disconnect)
    78→    event_loop_handle: Arc<RwLock<Option<JoinHandle<()>>>>,
    79→    /// Whether auto-reconnection is enabled (disabled on manual disconnect)
    80→    reconnect_enabled: Arc<AtomicBool>,
    81→    /// Current reconnection attempt counter (shared across reconnection tasks)
    82→    reconnect_attempt: Arc<std::sync::atomic::AtomicU32>,
    83→    /// Credential store for securely retrieving MQTT passwords from OS keyring
    84→    credential_store: Arc<MqttCredentialStore>,
    85→}
