   134→        credential_store: Arc<MqttCredentialStore>,
   135→    ) -> JoinHandle<()> {
   136→        tokio::spawn(async move {
   137→            loop {
   138→                match event_loop.poll().await {
   139→                    Ok(event) => {
   140→                        // Reset reconnection counter on successful event (connection established)
   141→                        if matches!(event, Event::Incoming(Incoming::ConnAck(_))) {
