   157→                                Arc::clone(&event_loop_handle),
   158→                                Arc::clone(&reconnect_enabled),
   159→                                Arc::clone(&reconnect_attempt),
   160→                                Arc::clone(&credential_store),
   161→                            );
   162→                        }
